export interface UnitEconomics {
  sourcingPrice: number;
  shippingDDP: number;
  amazonSellingPrice: number;
  amazonFBAFee: number;
}

export const ProfitEngine: React.FC<{ initialData?: UnitEconomics }> = () => {
  const [sourcing, setSourcing] = useState(6.20);
  const [shipping, setShipping] = useState(2.50);
  const [price, setPrice] = useState(29.99);
  const [fba, setFba] = useState(4.15);

  const landedCost = sourcing + shipping;
  const referralFee = price * 0.15;
  const netProfit = price - (landedCost + referralFee + fba);
  const margin = ((netProfit / price) * 100).toFixed(1);

  return (
    <div className="p-4 rounded-xl bg-slate-900 border border-slate-800 text-white">
      <h3 className="text-sm font-bold text-cyan-400">Autonomous Profit Modeler</h3>
      <div className="mt-2 text-xs flex justify-between">
        <span>Landed Cost: \${landedCost.toFixed(2)}</span>
        <span className="text-emerald-400 font-bold">Net Margin: {margin}%</span>
      </div>
    </div>
  );
};
